content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体的法律合规性与信息真实性",
            "check_points": [
                "通过权威工商登记及司法公开平台（如国家企业信用信息公示系统、中国裁判文书网）核查该主体是否存在未结重大诉讼、仲裁、被执行、失信或行政处罚记录",
                "核对营业执照所载经营范围，确认合同项下标的（尤其服务内容或产品类型）属于其法定经营范围内",
                "逐项比对合同中列明的主体信息（统一社会信用代码、全称、注册地址、联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如合同涉及软件采购或技术产品，核查卖方是否为该软件/产品的合法著作权人或已获有效授权，要求提供权属证明或授权链文件"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保核心条款要素齐全、逻辑闭环、无结构性缺失",
            "check_points": [
                "检查合同是否完整包含以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量标准与保证、交付方式/时间/地点、验收标准/程序/时限、项目完成时限、违约责任（含违约金计算方式与上限）、争议解决方式（管辖法院或仲裁机构）、不可抗力定义与处理机制、廉洁承诺条款、合同变更程序、合同份数及效力说明、电子送达效力约定",
                "确认合同已明确指定主要项目负责人，并完整记载其姓名、居民身份证号码及联系电话",
                "核查采购内容描述是否具体明确：包括但不限于品种、规格、型号、等级、花色等技术参数；若需细化，应注明‘详见附件X’且附件已作为合同组成部分签署",
                "核验合同金额表述：数量单位清晰、单价与总价准确对应、币种明确（如人民币/USD）、大小写一致；总价须与各分项合计严格吻合；禁止仅写‘按实结算’等模糊表述而无计价依据",
                "审查付款计划：是否设置明确的里程碑节点（如签约后、到货验收后、初验通过后、终验合格后、维保期满后），各节点付款比例及金额可计算；是否预留不低于5%尾款于免费维保期届满后支付；是否明确发票类型（增值税专用发票/普通发票）及开票时点"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定精确、无歧义，时间计算规则明确",
            "check_points": [
                "合同期限是否以起止日期（年/月/日）或具体时长（如‘自2025年1月1日起至2026年12月31日止’）方式明确约定",
                "若采用周期表述（如‘一年’‘季度’），是否明确定义计算基准（例如：‘自合同生效日起连续12个自然月’或‘自2025年1月1日起至2025年12月31日止’）",
                "所有时间表述是否统一标注计数基准：如‘工作日’须明确定义（如‘指中国大陆境内银行正常营业日，不含法定节假日’），‘自然日’‘自然季度’等术语是否无歧义；避免使用‘尽快’‘及时’‘适时’等模糊用语"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同语言严谨、格式统一、内外一致",
            "check_points": [
                "全文通读排查错别字、标点误用、语法错误、语序混乱、主谓不一致等基础文字问题",
                "核对正文与所有附件（技术规格书、服务清单、报价明细、廉洁协议等）中相同条款（如付款条件、验收标准、知识产权归属、违约责任）是否表述完全一致，无冲突或矛盾",
                "清理招标、谈判、询价等前期流程中遗留的非合同用语（如‘投标单位’‘响应人’‘谈判小组’‘评标办法’等），统一替换为‘甲方’‘乙方’‘本合同’等正式合同主体称谓",
                "验证合同首部‘甲方/乙方’全称、签约页落款名称、盖章处名称三者完全一致，无缩写、错字、漏字或括号差异（如‘有限公司’与‘有限责任公司’）",
                "核查所援引法律法规名称、条款序号是否准确有效（如《民法典》第509条而非已废止的《合同法》），并确认该法律现行有效且适用于本合同类型",
                "确认合同正文末尾是否规范标注‘以下为合同签署栏’或‘以下无正文’字样，防止空白页被擅自添加内容"
            ]
        }
    ]
}
